pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address k, address other) public {
        vm.assume(k != other);
        // this contract is the deployer, hence the owner; approve k...
        c.setApprovedLogger(k, true);
        // ...then have the owner revoke a DIFFERENT address
        c.setApprovedLogger(other, false);
        // k's approval must have been recorded on k's key and must persist:
        // in P approvedLoggers(k) is true; in M every write landed on
        // msg.sender, so approvedLoggers(k) is false.
        assertTrue(c.approvedLoggers(k));
    }
}

