    function test(bytes32 digest, bytes32 r, bytes32 s) public {
        // this contract was never approved as a logger
        require(!c.approvedToLog(address(this)), "must be unapproved");
        bool result = c.logGotRedemptionSignature(digest, r, s);
        assert(result == false);
